+                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
+                    break;
+                case "Appearance":
+                    savedAppearance = await SettingsService.GetAppearanceAsync();
+                    PopulateAppearanceFields(savedAppearance);
+                    break;
+            }
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    // Profile methods
+    private void PopulateProfileFields(UserProfile profile)
+    {
+        editDisplayName = profile.DisplayName;
+        editEmail = profile.Email;
+        editBio = profile.Bio;
+        editAvatarUrl = profile.AvatarUrl;
+    }
+
+    private async Task SaveProfile()
+    {
+        isSaving = true;
+        try
+        {
+            var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
+            await SettingsService.SaveProfileAsync(updated);
+            savedProfile = updated;
+            ShowToast("Profile saved successfully!", "success");
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Error saving profile: {ex.Message}", "error");
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (savedProfile != null)
+        {
+            PopulateProfileFields(savedProfile);
+        }
+    }
+
+    // Notifications methods
+    private void PopulateNotificationFields(NotificationPrefs prefs)
+    {
+        editEmailNotifications = prefs.EmailNotifications;
+        editPushNotifications = prefs.PushNotifications;
+        editWeeklyDigest = prefs.WeeklyDigest;
+        editMutedChannels = new List<string>(prefs.MutedChannels);
+    }
+
+    private void ToggleMutedChannel(string channel, bool isMuted)
+    {
+        if (isMuted && !editMutedChannels.Contains(channel))
+        {
+            editMutedChannels.Add(channel);
+        }
+        else if (!isMuted)
+        {
+            editMutedChannels.Remove(channel);
+        }
+    }
+
+    private async Task SaveNotifications()
+    {
+        isSaving = true;
+        try
+        {
+            var updated = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
+            await SettingsService.SaveNotificationPrefsAsync(updated);
+            savedNotificationPrefs = updated;
+            ShowToast("Notification preferences saved!", "success");
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Error saving preferences: {ex.Message}", "error");
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    // Security methods
+    private void TogglePasswordPanel()
+    {
+        showPasswordPanel = !showPasswordPanel;
+        passwordError = "";
+    }
+
+    private async Task UpdatePassword()
+    {
+        passwordError = "";
+
+        if (string.IsNullOrWhiteSpace(currentPassword))
+        {
+            passwordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(newPassword))
+        {
+            passwordError = "New password is required.";
+            return;
+        }
+        if (newPassword != confirmPassword)
+        {
+            passwordError = "New password and confirmation do not match.";
+            return;
+        }
+
+        isSaving = true;
+        try
+        {
+            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+            showPasswordPanel = false;
+            ShowToast("Password updated successfully!", "success");
+        }
+        catch (Exception ex)
+        {
+            passwordError = ex.Message;
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    private void RequestRevoke(ActiveSession session)
+    {
+        revokeSessionId = session.Id;
+        revokeSessionDevice = session.Device;
+        showRevokeConfirmation = true;
+    }
+
+    private void CancelRevoke()
+    {
+        showRevokeConfirmation = false;
+        revokeSessionId = "";
+        revokeSessionDevice = "";
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        try
+        {
+            await SettingsService.RevokeSessionAsync(revokeSessionId);
+            securitySettings = await SettingsService.GetSecuritySettingsAsync();
+            ShowToast("Session revoked successfully.", "success");
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Error revoking session: {ex.Message}", "error");
+        }
+        finally
+        {
+            showRevokeConfirmation = false;
+            revokeSessionId = "";
+            revokeSessionDevice = "";
+        }
+    }
+
+    // Appearance methods
+    private void PopulateAppearanceFields(AppearanceSettings settings)
+    {
+        editTheme = settings.Theme;
+        editFontSize = settings.FontSize;
+        editLanguage = settings.Language;
+        editCompactMode = settings.CompactMode;
+    }
+
+    private string GetPreviewClasses()
+    {
+        var classes = $"preview-theme-{editTheme.ToLowerInvariant()} preview-font-{editFontSize.ToLowerInvariant()}";
+        if (editCompactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private async Task SaveAppearance()
+    {
+        isSaving = true;
+        try
+        {
+            var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
+            await SettingsService.SaveAppearanceAsync(updated);
+            savedAppearance = updated;
+            ShowToast("Appearance settings saved!", "success");
+        }
+        catch (Exception ex)
+        {
+            ShowToast($"Error saving appearance: {ex.Message}", "error");
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    // Toast helper
+    private void ShowToast(string message, string type)
+    {
+        toastCts?.Cancel();
+        toastMessage = message;
+        toastType = type;
+
+        toastCts = new CancellationTokenSource();
+        var token = toastCts.Token;
+
+        _ = Task.Run(async () =>
+        {
+            await Task.Delay(4000, token);
+            if (!token.IsCancellationRequested)
+            {
+                await InvokeAsync(() =>
+                {
+                    toastMessage = "";
+                    StateHasChanged();
+                });
+            }
+        }, token);
+    }
+
+    private void DismissToast()
+    {
+        toastCts?.Cancel();
+        toastMessage = "";
+    }
+}
